import React, { useState } from "react";
import ErrorModal from "./error-modal";
import "./sty.css";

const UserForm = (props) => {
  const [username, setUsername] = useState("");
  const [age, setAge] = useState("");
  const [valid, setValid] = useState(true);

  const onUsernameChange = (event) => {
    setUsername(event.target.value);
  };

  const onAgeChange = (event) => {
    setAge(event.target.value);
  };

  const onFormSubmit = (event) => {
    event.preventDefault();

    if (username.trim().length == 0 || isNaN(age) || age < 0) {
      setValid(false);
      setUsername("");
      setAge("");
      return;
    }

    setValid(true);
    props.onAddUser({ username, age });
  };

  return (
    <div>
      <form onSubmit={onFormSubmit}>
        <div className="form-control">
          <label htmlFor="username">Username</label>
          <input type="number" id="username" value={username} onChange={onUsernameChange} />
          <label htmlFor="age" id="age">Age (Years)</label>
          <input type="number" value={age} onChange={onAgeChange} />
        </div>
        <button type="submit" onClick={onFormSubmit}>
          Add User
        </button>
      </form>
      <ErrorModal show={!valid} />
    </div>
  );
};

export default UserForm;
